function formatPhone(phone) {
  if (!phone) return '';
  let clean = String(phone).replace(/[\s\-\(\)\+]/g, '');
  if (clean.startsWith('0')) clean = '92' + clean.slice(1);
  return clean;
}

function karachiDateString(d) {
  // Returns YYYY-MM-DD computed in Asia/Karachi, not UTC (fixes the midnight drift bug)
  return d.toLocaleDateString('en-CA', { timeZone: 'Asia/Karachi' });
}

const rawMessage = $input.first().json.messages?.[0]?.text?.body || '';
const rawPhone = $input.first().json.contacts?.[0]?.wa_id || '';
const waMessageId = $input.first().json.messages?.[0]?.id || '';
const formattedPhone = formatPhone(rawPhone);

const now = new Date();
const todayKarachi = karachiDateString(now);

const availableDates = [];
for (let i = 0; i <= 2; i++) {
  const d = new Date(now.getTime() + i * 24 * 60 * 60 * 1000);
  const formattedDate = karachiDateString(d);
  const dayName = d.toLocaleDateString('en-US', { weekday: 'short', timeZone: 'Asia/Karachi' });
  availableDates.push(`${formattedDate} (${dayName})`);
}

return [{
  json: {
    user_message: rawMessage,
    sender_phone: formattedPhone,
    wa_message_id: waMessageId,
    today_date: todayKarachi,
    next_3_days: availableDates,
    has_text: rawMessage.trim().length > 0
  }
}];

// Resolve session_id, expiring after 30 minutes of inactivity.
// A new session_id means the AI Agent's memory (keyed on session_id) starts fresh automatically.
const items = $input.all().filter(r => r.json && r.json.whatsapp_number);
const upstream = $('Date & Time Generator').first().json;
const now = new Date();
const THIRTY_MIN_MS = 30 * 60 * 1000;

let sessionId;
let needsNewRow = true;

if (items.length > 0) {
  const row = items[0].json;
  const lastActive = row.last_active_at ? new Date(row.last_active_at) : null;
  if (lastActive && (now.getTime() - lastActive.getTime()) < THIRTY_MIN_MS) {
    sessionId = row.session_id;
    needsNewRow = false; // existing row just needs last_active_at bumped
  } else {
    sessionId = upstream.sender_phone + '_' + now.getTime();
  }
} else {
  sessionId = upstream.sender_phone + '_' + now.getTime();
}

return [{
  json: {
    ...upstream,
    session_id: sessionId,
    session_needs_new_row: needsNewRow,
    last_active_at: now.toISOString()
  }
}];

