const text = $input.first().json.output || '';
const session = $('Resolve Session').first().json;

function clean(t) {
  return t.replace(/BOOKING_CONFIRMED:[\s\S]*/, '')
          .replace(/RESCHEDULE_CONFIRMED:[\s\S]*/, '')
          .replace(/CANCEL_CONFIRMED:[\s\S]*/, '')
          .trim();
}

const bookingMatch = text.match(/BOOKING_CONFIRMED:\s*([0-9-]+)\s*\|\s*([0-9:]+)\s*\|\s*([^|]+)\|\s*([^|]+)\|\s*([^|]+)\|\s*([^|]+)\|\s*([A-Za-z0-9_-]+)/);
const rescheduleMatch = text.match(/RESCHEDULE_CONFIRMED:\s*([A-Za-z0-9_-]+)\s*\|\s*([0-9-]+)\s*\|\s*([0-9:]+)/);
const cancelMatch = text.match(/CANCEL_CONFIRMED:\s*([A-Za-z0-9_-]+)/);

let action = 'none';
let out = { ...session, reply_text: clean(text) };

if (bookingMatch) {
  action = 'booking';
  out.date = bookingMatch[1].trim();
  out.time = bookingMatch[2].trim();
  out.name = bookingMatch[3].trim();
  out.age = bookingMatch[4].trim();
  out.gender = bookingMatch[5].trim();
  out.booker_name = bookingMatch[6].trim();
  out.patient_ref = bookingMatch[7].trim(); // 'NEW' or an existing patient_id
} else if (rescheduleMatch) {
  action = 'reschedule';
  out.appointment_id = rescheduleMatch[1].trim();
  out.new_date = rescheduleMatch[2].trim();
  out.new_time = rescheduleMatch[3].trim();
} else if (cancelMatch) {
  action = 'cancel';
  out.appointment_id = cancelMatch[1].trim();
}

out.action = action;
return [{ json: out }];

// FIX: alwaysOutputData forces one empty item even when nothing matched.
// Only count a row as a real conflict if it actually has an appointment_id.
const rows = $input.all().filter(r => r.json && r.json.appointment_id);
const activeConflict = rows.some(r => r.json.Status !== 'Cancelled');
return [{ json: { ...$('Parse Agent Output').first().json, still_open: !activeConflict } }];

const rows = $input.all().filter(r => r.json && r.json.appointment_id);
const found = rows.length > 0;
const isConfirmed = found && rows[0].json.Status === 'Confirmed';
return [{ json: {
  ...$('Parse Agent Output').first().json,
  found,
  is_confirmed: isConfirmed,
  old_calendar_event_id: found ? rows[0].json.calendar_event_id : null,
  old_patient_id: found ? rows[0].json.patient_id : null
} }];

const rows = $input.all().filter(r => r.json && r.json.appointment_id);
const activeConflict = rows.some(r => r.json.Status !== 'Cancelled');
return [{ json: { ...$('Guard: Found & Confirmed (Reschedule)').first().json, still_open: !activeConflict } }];

const rows = $input.all().filter(r => r.json && r.json.appointment_id);
const found = rows.length > 0;
const isConfirmed = found && rows[0].json.Status === 'Confirmed';
return [{ json: {
  ...$('Parse Agent Output').first().json,
  found,
  is_confirmed: isConfirmed,
  calendar_event_id: found ? rows[0].json.calendar_event_id : null
} }];

function karachiDateString(d) {
  return d.toLocaleDateString('en-CA', { timeZone: 'Asia/Karachi' });
}

const now = new Date();
const tomorrow = new Date(now.getTime() + 24 * 60 * 60 * 1000);
const tomorrowKarachi = karachiDateString(tomorrow);

return [{
  json: {
    tomorrow_date: tomorrowKarachi
  }
}];

// Filter out rows missing appointment_id (phantom empty item)
// and rows where reminder_sent is already TRUE
const rows = $input.all().filter(r => r.json && r.json.appointment_id);
const unsent = rows.filter(r => {
  const val = String(r.json.reminder_sent || '').trim().toUpperCase();
  return val !== 'TRUE';
});
return unsent;

const patientRows = $input.all().filter(r => r.json && r.json.patient_id);
const patientName = patientRows.length > 0 ? patientRows[0].json.Name : 'there';
const appt = $('Split In Batches').item.json;

function to12Hour(t) {
  const [h, m] = t.split(':').map(Number);
  const period = h >= 12 ? 'PM' : 'AM';
  const hour12 = h % 12 === 0 ? 12 : h % 12;
  return `${hour12}:${String(m).padStart(2, '0')} ${period}`;
}

const message = `Hi ${patientName}, this is a reminder for your appointment tomorrow, ${appt.date} at ${to12Hour(appt.Time)} at Doctor Clinic.\nAppointment ID: ${appt.appointment_id}\nReply here if you need to reschedule or cancel.`;

return [{
  json: {
    output: message,
    sender_phone: appt.whatsapp_number,
    appointment_id: appt.appointment_id
  }
}];

function karachiDateString(d) {
  return d.toLocaleDateString('en-CA', { timeZone: 'Asia/Karachi' });
}

const todayKarachi = karachiDateString(new Date());

return [{
  json: {
    today_date: todayKarachi
  }
}];

// Drop the phantom empty item alwaysOutputData can produce
const rows = $input.all().filter(r => r.json && r.json.appointment_id);
return rows;

// Build a patient_id -> Name lookup map, then join it against today's appointments
const patients = $('Get All Patients').all();
const patientMap = {};
for (const p of patients) {
  if (p.json && p.json.patient_id) {
    patientMap[p.json.patient_id] = p.json.Name || 'Unknown';
  }
}

const appts = $('Filter Valid Rows').all();

function to12Hour(t) {
  const [h, m] = t.split(':').map(Number);
  const period = h >= 12 ? 'PM' : 'AM';
  const hour12 = h % 12 === 0 ? 12 : h % 12;
  return `${hour12}:${String(m).padStart(2, '0')} ${period}`;
}

// Sort by time ascending so the doctor sees the day in order
const sorted = [...appts].sort((a, b) => a.json.Time.localeCompare(b.json.Time));

const lines = sorted.map(r => {
  const name = patientMap[r.json.patient_id] || 'Unknown patient';
  return `• ${to12Hour(r.json.Time)} — ${name} (${r.json.appointment_id})`;
});

const today = $('Compute Today Date').first().json.today_date;
const message = `Good morning! Here is today's schedule (${today}) — ${sorted.length} appointment(s):\n\n` + lines.join('\n');

return [{
  json: {
    output: message
  }
}];
